<?php
require_once __DIR__.'/../bootstrap/app.php';require_any_role('RECEPTIONIST','SUPER_ADMIN');$rows=db_all("SELECT g.*,m.Name,m.MemberNumber,ci.Email CheckedInByEmail,co.Email CheckedOutByEmail FROM GYM_ATTENDANCE g JOIN MEMBER m ON m.MemberID=g.MemberID JOIN USER_ACCOUNT ci ON ci.UserID=g.CheckedInBy LEFT JOIN USER_ACCOUNT co ON co.UserID=g.CheckedOutBy ORDER BY g.CheckInAt DESC LIMIT 200");$pageTitle='Gym visit history';$pageSubtitle='Reception-recorded check-ins and check-outs';include ROOT_PATH.'/includes/header.php';?><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Member</th><th scope="col">Check in</th><th scope="col">Check out</th><th scope="col">Status</th><th scope="col">Recorded by</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['Name'])?><br><small><?=e($r['MemberNumber'])?></small></td><td><?=e(date('d M Y H:i',strtotime($r['CheckInAt'])))?></td><td><?=$r['CheckOutAt']?e(date('d M Y H:i',strtotime($r['CheckOutAt']))):'—'?></td><td><span class="badge <?=$r['Status']==='CHECKED_IN'?'badge-green':'badge-grey'?>"><?=e($r['Status'])?></span></td><td><?=e($r['CheckedInByEmail'])?></td></tr><?php endforeach;?></tbody></table></div><?php include ROOT_PATH.'/includes/footer.php';?>
